#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
    }
    vector<int> front(l.begin(), l.begin() + n / 2);
    vector<int> back(l.begin() + n / 2, l.end());

    int front_len = n / 2;
    int back_len = n - front_len;

    int front_mask = 1 << front_len;
    int back_mask = 1 << back_len;

    vector<int> front_sums;
    for (int mask = 0; mask < front_mask; ++mask) {
        int total = 0;
        for (int i = 0; i < front_len; ++i) {
            if (mask & (1 << i)) {
                total += front[i];
            }
        }
        front_sums.push_back(total % m);
    }

    vector<int> back_sums;
    for (int mask = 0; mask < back_mask; ++mask) {
        int total = 0;
        for (int i = 0; i < back_len; ++i) {
            if (mask & (1 << i)) {
                total += back[i];
            }
        }
        back_sums.push_back(total % m);
    }

    sort(front_sums.begin(), front_sums.end());
    sort(back_sums.begin(), back_sums.end());

    int max_modulo = 0;

    auto binary_search_for = [&](const vector<int>& l, int x) {
        int left = 0, right = (int)l.size() - 1;
        int res = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (l[mid] < x) {
                res = l[mid];
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    };

    for (int s : front_sums) {
        int needed = m - s;
        int candidate = binary_search_for(back_sums, needed);
        max_modulo = max(max_modulo, (s + candidate) % m);
    }

    cout << max_modulo << "\n";

    return 0;
}
